def rotated_minimum(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        middle = (left + right) // 2
        if nums[middle] > nums[right]:
            left = middle + 1
        elif nums[middle] < nums[right]:
            right = middle
        else:
            right -= 1
    return nums[left]

